import UIKit
import os

/// Web screens' module calls log from React Native's threads, so not through the main actor.
private let webModuleLog = Logger(subsystem: "dev.farmjs.mobile.shell", category: "FarmShell")

/// React Native for `page.native.tsx` screens (RFC 0004, 7.2). Generated by @farm.js/mobile/ios
/// only for apps with React Native screens; it replaces the stub an app without them gets. New
/// architecture only (Hermes, Fabric, bridgeless). One runtime is shared by every native screen,
/// each its own surface in the navigator's screen, the same container a web screen's WebView uses.
@MainActor
func createFarmNativeEngine(config: RouteConfig) -> FarmNativeEngine? {
    guard let bundle = FarmReactNativeBuild.bundleURL else {
        Navigator.log.error("react-native bundle missing from the app; native screens show their web twin")
        return nil
    }
    return ReactNativeEngine(config: config, bundleURL: bundle)
}

@MainActor
final class ReactNativeEngine: FarmNativeEngine {
    private let config: RouteConfig
    private let runtime: FarmReactNative
    private let session = FarmReactNativeSessionAdapter()
    private var nextScreen = 1
    private var warmStarted: CFTimeInterval?

    init(config: RouteConfig, bundleURL: URL) {
        self.config = config
        runtime = FarmReactNative(bundleURL: bundleURL, dev: FarmBuild.dev)
        FarmReactNative.session = session
        runtime.onStarted = { [weak self] in
            guard let self, let started = self.warmStarted else { return }
            let ms = Int((CACurrentMediaTime() - started) * 1000)
            Navigator.log.notice("react-native warm in \(ms)ms dev=\(FarmBuild.dev)")
        }
    }

    func warm() {
        if warmStarted == nil { warmStarted = CACurrentMediaTime() }
        runtime.warm()
    }

    func open(host: FarmNativeHost, rule: RouteConfig.Rule, url: URL) -> FarmNativeContent? {
        guard let module = rule.module else { return nil }
        if warmStarted == nil { warmStarted = CACurrentMediaTime() }
        let screen = nextScreen
        nextScreen += 1
        let bridge = ScreenBridge(host: host)
        let properties: [String: Any] = [
            "screen": screen,
            "url": url.absoluteString,
            "route": rule.route ?? (url.path.isEmpty ? "/" : url.path),
            "server": config.server.absoluteString,
        ]
        guard let view = runtime.openModule(module, screen: screen, properties: properties, host: bridge) else {
            return nil
        }
        let controller = ReactNativeScreenController(content: view)
        return FarmNativeContent(controller) { [weak runtime] in
            runtime?.closeScreen(screen)
        }
    }

    /// A web screen's call to an app module (FarmWebModules.swift), on the instance native screens
    /// use. `arguments` are already checked against the spec; `reply` may run on any thread.
    func callModule(
        _ name: String,
        selector: String,
        arguments: [Any],
        reply: @escaping @Sendable (FarmCallReply) -> Void
    ) {
        if warmStarted == nil { warmStarted = CACurrentMediaTime() }
        let started = CACurrentMediaTime()
        // Selector names are Codegen's, so the method is the part before the first colon.
        let call = "\(name).\(selector.prefix { $0 != ":" })"
        runtime.callModule(name, selector: selector, arguments: arguments) { json, code, message in
            let ms = Int((CACurrentMediaTime() - started) * 1000)
            if let json {
                webModuleLog.notice("web module \(call, privacy: .public) ok in \(ms)ms")
                reply(.json(json))
            } else {
                let code = code ?? "native_error"
                webModuleLog.notice("web module \(call, privacy: .public) failed (\(code, privacy: .public)) in \(ms)ms")
                reply(.failure(FarmCallError(code: code, message: message ?? "Native call failed.")))
            }
        }
    }
}

/// The view controller a React Native surface is shown in.
@MainActor
private final class ReactNativeScreenController: UIViewController {
    private let content: UIView

    init(content: UIView) {
        self.content = content
        super.init(nibName: nil, bundle: nil)
    }

    @available(*, unavailable)
    required init?(coder: NSCoder) {
        fatalError("ReactNativeScreenController is created in code")
    }

    override func loadView() {
        content.backgroundColor = Theme.background
        view = content
    }
}

/// Forwards FarmShell calls for one screen to its navigator host.
@MainActor
private final class ScreenBridge: NSObject, FarmReactNativeScreenHost {
    private weak var host: FarmNativeHost?

    init(host: FarmNativeHost) {
        self.host = host
    }

    func farmVisit(_ url: String, replace: Bool) {
        guard let target = URL(string: url) else { return }
        host?.visit(target, replace: replace)
    }

    func farmFallback(_ reason: String) {
        host?.fallback(reason)
    }

    func farmSetTitle(_ title: String) {
        host?.setTitle(title)
    }

    func farmRendered() {
        host?.rendered()
    }
}

/// The device session for the FarmShell module's session methods: `MobileSession` itself, so
/// tokens and cookies stay in native code.
@MainActor
private final class FarmReactNativeSessionAdapter: NSObject, FarmReactNativeSession {
    func farmSession(_ reply: @escaping (String?, String?) -> Void) {
        guard let session = MobileSession.shared else { return reply(nil, nil) }
        reply(session.appId, session.accessToken)
    }

    func farmRefreshSession(_ failedToken: String, reply: @escaping (String?) -> Void) {
        guard let session = MobileSession.shared else { return reply(nil) }
        Task { reply(await session.refresh(failed: failedToken)) }
    }

    func farmSignOut(_ reply: @escaping () -> Void) {
        guard let session = MobileSession.shared else { return reply() }
        Task {
            await session.signOut()
            reply()
        }
    }

    func farmSignIn(_ path: String, body: String, reply: @escaping (Int, String?, String?) -> Void) {
        guard let session = MobileSession.shared else { return reply(0, nil, "The device session is not ready.") }
        Task {
            do {
                let answer = try await session.signIn(path: path, body: body)
                reply(answer.status, answer.body, nil)
            } catch {
                reply(0, nil, String(describing: error))
            }
        }
    }
}
